operation.document:
query GetDocumentWithComments($id: String!, $commentsAfter: String) {
  document(id: $id) {
    id
    title
    slugId
    content
    url
    createdAt
    updatedAt
    creator {
      name
      email
    }
    project {
      name
      slugId
    }
    issue {
      identifier
      title
    }
    initiative {
      name
      slugId
    }
    team {
      name
      key
    }
    cycle {
      name
      number
      team {
        key
      }
    }
    release {
      name
      version
    }
    comments(first: 50, after: $commentsAfter, orderBy: createdAt) {
      nodes {
        id
        body
        quotedText
        documentContentId
        createdAt
        updatedAt
        archivedAt
        resolvedAt
        url
        user {
          name
          email
        }
        parent {
          id
        }
      }
      pageInfo {
        hasNextPage
        endCursor
      }
    }
  }
}

